begin;
create function kalling_private.execution_condition_ok(t kalling_private.execution_transactions,c jsonb,p_seen text[] default '{}') returns boolean language plpgsql stable security definer set search_path='' as $$
 declare dep text;x jsonb;cleared boolean;begin
 cleared=case c->>'kind' when 'Financing' then c->>'stage' in ('Funding confirmed','Not required (reviewed)') when 'Escrow' then c->>'stage' in ('Receipt confirmed','Not required (reviewed)') when 'License' then c->>'stage'='Continuity confirmed' when 'Premises' then c->>'stage' in ('Consent received','No consent required (reviewed)') when 'Purchase agreement' then c->>'stage'='Completion confirmed' when 'Other closing' then c->>'stage' in ('Confirmed','Not required (reviewed)') else false end;
 if c is null or c->>'id'=any(p_seen) or not coalesce(cleared,false) or (c#>>'{review,revision}')::integer is distinct from (c->>'revision')::integer or not kalling_private.execution_sources(t.id,c->'sources') then return false;end if;
 for dep in select * from jsonb_array_elements_text(c->'dependsOn') loop
 select z into x from jsonb_array_elements(t.data->'items') z where z->>'id'=dep;
 if x is not null then if not kalling_private.execution_item_ok(t,x) then return false;end if;else select z into x from jsonb_array_elements(t.data->'conditions') z where z->>'id'=dep;if not kalling_private.execution_condition_ok(t,x,p_seen||array[c->>'id']) then return false;end if;end if;end loop;return true;end $$;
create function public.kalling_execution_timeline(p_transaction uuid,p_revision integer,p_action text,p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
 declare t kalling_private.execution_transactions;d jsonb;c jsonb;n jsonb;items jsonb;key text;value text;dep text;x jsonb;allowed text[];stages text[];r text;clear boolean;begin
 select * into t from kalling_private.execution_transactions where id=p_transaction for update;r=kalling_private.execution_role(t.id);if r is distinct from 'advisor' or t.state in ('Closed','Abandoned') then raise exception 'Closing plan access denied' using errcode='42501';end if;if t.revision<>p_revision then raise exception 'This transaction changed. Reload before saving.';end if;d=t.data;
 if p_action='planning_date' then
 if not coalesce(to_char((p->>'date')::date,'YYYY-MM-DD')=p->>'date',false) then raise exception 'Choose a valid planning date.';end if;d=d||jsonb_build_object('planningClose',p->>'date');perform kalling_private.execution_save(t,d-'closePackage','Planning date changed','Contractual obligations are unchanged.');return kalling_private.execution_projection(t.id);end if;
 select z into c from jsonb_array_elements(d->'conditions') z where z->>'id'=p->>'id';
 if p_action='condition' then
 if p->>'id' is not null and c is null then raise exception 'Closing condition not found.';end if;
 case p->>'kind'
 when 'Financing' then allowed=array['lender','commitment','conditions','fundingEvidence','professional'];stages=array['Unknown','Pre-qualified','Underwriting','Commitment issued','Conditions cleared','Funding confirmed','Not required (reviewed)'];
 when 'Escrow' then allowed=array['coordinator','amount','currency','requirement','receipt','professional'];stages=array['Unknown','Requested','Receipt confirmed','Not required (reviewed)'];
 when 'License' then allowed=array['jurisdiction','currentRepresentative','proposedRepresentative','licenseVerification','verifiedOn','entityPlan','roleOwnership','continuity','filings','professional'];stages=array['Plan proposed','Professional review','Requirements confirmed','Continuity confirmed'];
 when 'Premises' then allowed=array['premises','leaseVersion','consentRequirement','landlordResponse','professional'];stages=array['Unknown','Lease review','Consent requested','Consent received','No consent required (reviewed)'];
 when 'Purchase agreement' then allowed=array['agreementVersion','executedEvidence','completionEvidence','professional'];stages=array['Draft','Executed','Completion confirmed'];
 when 'Other closing' then allowed=array['requirement','confirmation','professional'];stages=array['Pending','Confirmed','Not required (reviewed)'];
 else raise exception 'Choose a closing workstream.';end case;
 if not kalling_private.execution_safe(p->>'title',3,160) or not kalling_private.execution_safe(p->>'owner',2,120) or not kalling_private.execution_safe(p->>'nextAction',5,1000) or not coalesce(kalling_private.execution_deadline(p->'due'),false) or not coalesce(p->>'stage'=any(stages),false) or jsonb_typeof(p->'details') is distinct from 'object' or jsonb_typeof(p->'audience') is distinct from 'array' or jsonb_typeof(p->'dependsOn') is distinct from 'array' or jsonb_typeof(p->'sources') is distinct from 'array' or jsonb_typeof(p->'required') is distinct from 'boolean' then raise exception 'Record the condition, coordinator, next action and deadline or reason.';end if;
 for key,value in select * from jsonb_each_text(p->'details') loop if not (key=any(allowed)) or not kalling_private.execution_safe(value,0,1000) then raise exception 'Keep details within the stated workstream and exclude sensitive banking information.';end if;end loop;
 for key in select * from jsonb_array_elements_text(p->'audience') loop if key not in ('seller','buyer') and not exists(select 1 from kalling_private.execution_participants g where g.transaction_id=t.id and g.id::text=key and g.status='Active' and g.expires_at>now()) then raise exception 'Choose active transaction participants.';end if;end loop;
 if exists(select 1 from jsonb_array_elements(p->'sources') s where not kalling_private.execution_source(t.id,s)) then raise exception 'Refresh current evidence.';end if;
 n=jsonb_build_object('id',coalesce(c->>'id',gen_random_uuid()::text),'kind',p->>'kind','title',p->>'title','owner',p->>'owner','nextAction',p->>'nextAction','due',p->'due','audience',p->'audience','dependsOn',p->'dependsOn','required',p->'required','stage',p->>'stage','details',p->'details','sources',p->'sources','revision',coalesce((c->>'revision')::integer,0)+1,'history',coalesce(c->'history','[]'));
 elsif p_action='review_condition' then
 if c is null or (p->>'revision')::integer is distinct from (c->>'revision')::integer or not kalling_private.execution_safe(p->>'professional',3,160) or not kalling_private.execution_safe(p->>'note',30,2000) or not kalling_private.execution_sources(t.id,c->'sources') then raise exception 'Review the current condition, exact evidence and actual professional confirmation.';end if;
 clear=case c->>'kind' when 'Financing' then c->>'stage' in ('Funding confirmed','Not required (reviewed)') when 'Escrow' then c->>'stage' in ('Receipt confirmed','Not required (reviewed)') when 'License' then c->>'stage'='Continuity confirmed' when 'Premises' then c->>'stage' in ('Consent received','No consent required (reviewed)') when 'Purchase agreement' then c->>'stage'='Completion confirmed' when 'Other closing' then c->>'stage' in ('Confirmed','Not required (reviewed)') else false end;
 if not coalesce(clear,false) then raise exception 'A proposed plan, pre-qualification or requested consent does not clear a closing condition.';end if;
 allowed=case c->>'kind' when 'Financing' then array['lender','commitment','conditions','fundingEvidence'] when 'Escrow' then array['coordinator','amount','currency','requirement','receipt'] when 'License' then array['jurisdiction','currentRepresentative','proposedRepresentative','licenseVerification','verifiedOn','entityPlan','roleOwnership','continuity','filings'] when 'Premises' then array['premises','leaseVersion','consentRequirement','landlordResponse'] when 'Purchase agreement' then array['agreementVersion','executedEvidence','completionEvidence'] else array['requirement','confirmation'] end;
 if c->>'stage'<>'Not required (reviewed)' then foreach key in array allowed loop if not kalling_private.execution_safe(c->'details'->>key,2,1000) then raise exception 'Complete the actual confirmation details for %.',key;end if;end loop;end if;
 if c->>'kind'='License' and (coalesce(c#>>'{details,jurisdiction}','') not in ('NJ','NY') or not coalesce(to_char((c#>>'{details,verifiedOn}')::date,'YYYY-MM-DD')=c#>>'{details,verifiedOn}',false)) then raise exception 'Use a separate jurisdiction plan and an actual license verification date.';end if;
 if c->>'kind'='Escrow' and c->>'stage'<>'Not required (reviewed)' and (c#>>'{details,currency}'<>'USD' or c#>>'{details,amount}'!~'^[0-9]+([.][0-9]{1,2})?$') then raise exception 'Record the currency and exact referenced amount.';end if;
 for dep in select * from jsonb_array_elements_text(c->'dependsOn') loop select z into x from jsonb_array_elements(d->'items') z where z->>'id'=dep;if x is not null then if not kalling_private.execution_item_ok(t,x) then raise exception 'Resolve current dependencies first.';end if;else select z into x from jsonb_array_elements(d->'conditions') z where z->>'id'=dep;if not kalling_private.execution_condition_ok(t,x) then raise exception 'Clear current dependencies first.';end if;end if;end loop;
 n=c||jsonb_build_object('review',jsonb_build_object('revision',c->'revision','by',kalling_private.actor_name(),'at',now(),'professional',p->>'professional','note',p->>'note'),'nextAction','Keep this confirmation current until completion.');
 else raise exception 'Unknown closing-plan action';end if;
 n=jsonb_set(n,'{history}',coalesce(n->'history','[]')||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'action',p_action,'by',kalling_private.actor_name(),'at',now(),'note',coalesce(p->>'note',p->>'nextAction',''))));
 select coalesce(jsonb_agg(case when z->>'id'=n->>'id' then n else z end),'[]') into items from jsonb_array_elements(d->'conditions') z;if c is null then items=items||jsonb_build_array(n);end if;
 if not kalling_private.execution_graph(d->'items'||items) then raise exception 'Dependencies cannot form cycles or cross transactions.';end if;
 perform kalling_private.execution_save(t,jsonb_set(d-'closePackage','{conditions}',items),p_action,n->>'title');return kalling_private.execution_projection(t.id);end $$;
revoke all on function kalling_private.execution_condition_ok(kalling_private.execution_transactions,jsonb,text[]) from public,anon,authenticated;
revoke all on function public.kalling_execution_timeline(uuid,integer,text,jsonb) from public,anon;grant execute on function public.kalling_execution_timeline(uuid,integer,text,jsonb) to authenticated;
commit;

